-- ============================================================
-- Club history, from what the record can actually evidence.
--
-- player_history was the one table nothing wrote to. Two things fill it:
--
--   a team sheet naming a player in a club's squad, and
--   a scoring event credited to them for that club.
--
-- The second carries the older years. Line-ups exist only from 2024, but
-- scoring is recorded back to 2019, so for 2019, 2021, 2022, 2023 the events are the
-- only surviving evidence of who was where — 92 spells across
-- 47 players that a squad list alone would have missed entirely.
--
-- 767 spells across 486 players — 689 at clubs and 78
-- representative call-ups, kept apart in the role column. A call-up to the
-- national or President XIII side is a selection, not a transfer, and
-- reading it as a change of club would be wrong.
--
-- 38 players turn out for more than one club. Those are the genuine
-- moves; the rest is one club held across the seasons played.
--
-- Nothing is invented, and nothing is keyed on a name — every row uses the
-- player id the line-up or the event already holds. A spell built with no
-- team sheet behind it says so in its notes, so it is not mistaken for a
-- full squad record.
--
-- Appearance counts are in the notes too, so a spell of one game does not
-- read like a season. They count what is on record, not a career total:
-- only 33% of fixtures have a team sheet at all.
--
-- Safe to re-run: a spell already recorded for the same player, club and
-- season is left alone.
-- ============================================================

drop table if exists _ph_seed;

create temp table _ph_seed (
  player_id uuid,
  team      text,
  season    text,
  role      text,
  joined    date,
  left_dt   date,
  notes     text
);


select s.player_id, t.team_id, s.season, s.role, s.joined, s.left_dt, s.notes
from _ph_seed s
join teams t on t.name = s.team
where not exists (
  select 1 from player_history h
  where h.player_id = s.player_id
    and h.team_id = t.team_id
    and h.season is not distinct from s.season
);

drop table _ph_seed;
